package com.atelier.gestion.documento.service;
import static com.atelier.gestion.documento.dto.DocumentoDtos.*;
import com.atelier.gestion.auditoria.service.AuditoriaService;
import com.atelier.gestion.common.exception.*;
import com.atelier.gestion.common.storage.*;
import com.atelier.gestion.config.AtelierProperties;
import com.atelier.gestion.documento.entity.*;
import com.atelier.gestion.documento.repository.DocumentoRepository;
import com.atelier.gestion.estudio.entity.EstudioTecnico;
import com.atelier.gestion.estudio.repository.EstudioTecnicoRepository;
import com.atelier.gestion.expediente.entity.Expediente;
import com.atelier.gestion.expediente.repository.ExpedienteRepository;
import com.atelier.gestion.proyecto.repository.ProyectoRepository;
import com.atelier.gestion.proyecto.service.AutorizacionProyectoService;
import com.atelier.gestion.tramite.entity.TramitePublico;
import com.atelier.gestion.tramite.repository.TramitePublicoRepository;
import com.atelier.gestion.usuario.entity.Usuario;
import java.time.*;
import java.util.*;
import org.apache.commons.io.FilenameUtils;
import org.apache.commons.lang3.StringUtils;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;
import org.springframework.web.multipart.MultipartFile;
@Service public class DocumentoService{
  private final DocumentoRepository repo;private final ExpedienteRepository expedientes;private final EstudioTecnicoRepository estudios;private final TramitePublicoRepository tramites;private final ProyectoRepository proyectos;private final AutorizacionProyectoService acceso;private final ArchivoStorage storage;private final ValidadorArchivo validador;private final AtelierProperties props;private final AuditoriaService auditoria;private final Clock clock;
  public DocumentoService(DocumentoRepository r,ExpedienteRepository e,EstudioTecnicoRepository es,TramitePublicoRepository tr,ProyectoRepository p,AutorizacionProyectoService a,ArchivoStorage s,ValidadorArchivo v,AtelierProperties pr,AuditoriaService au,Clock c){repo=r;expedientes=e;estudios=es;tramites=tr;proyectos=p;acceso=a;storage=s;validador=v;props=pr;auditoria=au;clock=c;}
  @Transactional(readOnly=true) public List<Respuesta> listar(UUID expedienteId){Expediente e=expediente(expedienteId);Usuario u=acceso.usuario();acceso.verificarVisible(e.getProyecto(),u);List<Documento> lista="CLIENTE".equals(u.getRol().getNombre())?repo.findByExpedienteIdAndVigenteTrueAndVisibleClienteTrueOrderByCreadoEnDesc(expedienteId):repo.findByExpedienteIdAndVigenteTrueOrderByCreadoEnDesc(expedienteId);return lista.stream().map(this::dto).toList();}
  @Transactional(readOnly=true) public Respuesta obtener(UUID id){Documento d=repo.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Documento no encontrado"));Usuario u=acceso.usuario();acceso.verificarVisible(d.getExpediente().getProyecto(),u);if("CLIENTE".equals(u.getRol().getNombre())&&(!d.isVisibleCliente()||!d.isVigente()))throw new AccessDeniedException("Documento no autorizado para el cliente");return dto(d);}
  @Transactional public Respuesta subir(UUID expedienteId,String tipoDocumento,CategoriaDocumento categoria,UUID estudioId,UUID tramiteId,boolean visibleCliente,MultipartFile archivo){Expediente e=expedienteBloqueado(expedienteId);Usuario u=acceso.usuario();exigirCarga(e,u);boolean gestor=acceso.esGestor(u);if(visibleCliente&&!gestor)throw new AccessDeniedException("Solo un gestor puede autorizar documentos al cliente");if(categoria==CategoriaDocumento.PROPUESTA)throw new ReglaNegocioException("Las propuestas se cargan desde su propio flujo");EstudioTecnico estudio=null;TramitePublico tramite=null;if(categoria==CategoriaDocumento.ESTUDIO){if(estudioId==null)throw new ReglaNegocioException("Un documento de estudio exige estudioId");estudio=estudios.findById(estudioId).orElseThrow(()->new RecursoNoEncontradoException("Estudio no encontrado"));if(!estudio.getProyecto().getId().equals(e.getProyecto().getId()))throw new ReglaNegocioException("El estudio no pertenece al expediente");if("ESPECIALISTA".equals(u.getRol().getNombre())&&(estudio.getResponsable()==null||!u.getId().equals(estudio.getResponsable().getUsuario().getId())))throw new AccessDeniedException("Solo el responsable puede adjuntar el estudio");}else if(estudioId!=null)throw new ReglaNegocioException("estudioId solo aplica a documentos de estudio");if(Set.of(CategoriaDocumento.TRAMITE,CategoriaDocumento.RESOLUCION).contains(categoria)){if(!gestor)throw new AccessDeniedException("Solo un gestor puede adjuntar documentos del trámite");if(tramiteId==null)throw new ReglaNegocioException("El documento de trámite exige tramiteId");tramite=tramites.findById(tramiteId).orElseThrow(()->new RecursoNoEncontradoException("Trámite no encontrado"));if(!tramite.getProyecto().getId().equals(e.getProyecto().getId()))throw new ReglaNegocioException("El trámite no pertenece al expediente");}else if(tramiteId!=null)throw new ReglaNegocioException("tramiteId solo aplica a documentos de trámite o resolución");
    validador.validar(archivo);String tipo=StringUtils.trim(tipoDocumento);if(StringUtils.isBlank(tipo)||tipo.length()>50)throw new ReglaNegocioException("El tipo de documento es obligatorio y admite hasta 50 caracteres");String nombre=sanitizar(archivo.getOriginalFilename());String carpeta="atelier/%s/proyectos/%s/%s".formatted(props.environment(),e.getProyecto().getCodigo(),carpeta(categoria));ArchivoAlmacenado subido=storage.subir(archivo,carpeta);compensar(subido);short version=(short)(repo.maxVersion(expedienteId,tipo,categoria,estudioId,tramiteId)+1);repo.vigentesDeSerie(expedienteId,tipo,categoria,estudioId,tramiteId).forEach(Documento::retirar);Documento d=repo.save(new Documento(e,u,estudio,tramite,nombre,tipo,version,subido.secureUrl(),subido.publicId(),StringUtils.lowerCase(FilenameUtils.getExtension(nombre)),subido.tipoMime(),subido.tamanoBytes(),categoria,subido.resourceType(),visibleCliente,OffsetDateTime.now(clock)));auditoria.registrar(u,"documentos",d.getId(),"INSERT",Map.of("publicId",subido.publicId(),"categoria",categoria.name()));return dto(d);}
  @Transactional public void eliminar(UUID id){Documento d=repo.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Documento no encontrado"));Usuario u=acceso.usuario();acceso.verificarVisible(d.getExpediente().getProyecto(),u);boolean gestor=acceso.esGestor(u);if(!gestor&&!u.getId().equals(d.getSubidoPor().getId()))throw new AccessDeniedException("Solo el autor o un gestor puede retirar el documento");if(!d.isVigente())return;if(!storage.eliminar(d.getPublicIdCloudinary(),d.getResourceType()))throw new ReglaNegocioException("Cloudinary no confirmó la eliminación; el documento se conserva vigente");d.retirar();auditoria.registrar(u,"documentos",id,"DELETE",Map.of("publicId",d.getPublicIdCloudinary()));}
  private Expediente expediente(UUID id){return expedientes.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Expediente no encontrado"));}
  private Expediente expedienteBloqueado(UUID id){return expedientes.bloquear(id).orElseThrow(()->new RecursoNoEncontradoException("Expediente no encontrado"));}
  private void exigirCarga(Expediente e,Usuario u){if(acceso.esGestor(u))return;if("ESPECIALISTA".equals(u.getRol().getNombre())&&proyectos.asignadoA(e.getProyecto().getId(),u.getCorreo()))return;throw new AccessDeniedException("No puede cargar documentos en este expediente");}
  private String carpeta(CategoriaDocumento categoria){return switch(categoria){case ESTUDIO->"estudios";case TRAMITE->"tramites";case RESOLUCION->"resoluciones";default->"expediente";};}
  private String sanitizar(String original){String nombre=StringUtils.trim(FilenameUtils.getName(StringUtils.defaultIfBlank(original,"documento"))).replaceAll("[\\p{Cntrl}]","");if(nombre.isBlank())nombre="documento";return StringUtils.left(nombre,200);}
  private void compensar(ArchivoAlmacenado a){if(!TransactionSynchronizationManager.isSynchronizationActive())throw new IllegalStateException("La carga requiere una transacción activa");TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCompletion(int status){if(status!=STATUS_COMMITTED)storage.eliminar(a.publicId(),a.resourceType());}});}
  private Respuesta dto(Documento d){var u=d.getSubidoPor();return new Respuesta(d.getId(),d.getExpediente().getId(),d.getExpediente().getProyecto().getId(),d.getEstudio()==null?null:d.getEstudio().getId(),d.getTramite()==null?null:d.getTramite().getId(),u.getId(),u.getNombres()+" "+u.getApellidos(),d.getNombre(),d.getTipoDocumento(),d.getVersion(),d.getUrlCloudinary(),d.getPublicIdCloudinary(),d.getFormato(),d.getTipoMime(),d.getTamanoBytes(),d.getCategoria(),d.getResourceType(),d.isVisibleCliente(),d.isVigente(),d.getCreadoEn());}
}
